#!/usr/bin/env python3
import re
from ta_emss import ta_emss


if __name__ == "__main__":

    ################################################################################
    # Create EMSS instance and connect with BTS OAM
    ################################################################################
    emss1 = ta_emss()
    emss1.setup_emss(bts_id=1)

    ################################################################################
    # Configure Xterminator with 254 eNBs
    ################################################################################
    print("Setting xterminator up...")
    emss1.xterm_setup(
        # BTS section
        bts_ip_addr="10.0.1.2",
        # GNBsim local IP section
        gnbsim_ip_addr_begin="10.0.201.1",
        gnbsim_ip_addr_end="10.0.201.2",
        gnbsim_ip_addr_mask=24,
        gnbsim_eth_if="eth3",
        # General params
        verbose=True,
        debug=False,
    )

    ################################################################################
    # Add NRRELs from simulated gNBs to each BTS cell
    ################################################################################

    nrcels = emss1.get_existing_objects_of_given_type('NRCELL')
    print("NR Cells={}".format(nrcels))
    moc_tab = []
    for nrrel_id, gnb in enumerate(emss1.xterm_get("gnbs"), start=1):
        gnb_id = gnb["GNB_ID"]
        gnb_ip = gnb["IP_ADDR"]
        mcc = gnb["MCC"]
        mnc = gnb["MNC"]
        print("GNB={}, mcc={}, mnc={}".format(gnb_id, mcc, mnc))
        moc_tab.append({'MOC': 'NRADJGNB', 'ID': f'{nrrel_id}',
                        'gNodeBId': gnb_id,
                        'gnbPlmn': [{'mcc': mcc, 'mnc': mnc, 'mncLength': len(mnc)}]})
        moc_tab.append({'MOC': 'NRADJNRCELL', 'ID': f'{nrrel_id}',
                        'gNbId': gnb_id,
                        'lcrId': 1,
                        'nrarfcn': 643000,
                        'physCellId': nrrel_id,
                        'ssbFrequency': 1,
                        'freqBandIndicatorNR': 78,
                        'gnbPlmn': [{'mcc': mcc, 'mnc': mnc, 'mncLength': len(mnc)}]})
        for nrcel in nrcels:
            nrcel_id = re.search(r'(\d+)', nrcel).group(1)
            moc_tab.append({'MOC': 'NRCELL', 'ID': f'{nrcel_id}', 'actK1Opt': 'intraAndInter-gNB'})
            moc_tab.append({'MOC': 'NRREL', 'ID': f'{nrcel_id}-{nrrel_id}',
                            'gNbId': gnb_id,
                            'lcrId': 1,
                            'gnbPlmn': [{'mcc': mcc, 'mnc': mnc, 'mncLength': len(mnc)}],
            })
    emss1.configure_bts(moc_tab)

    print("Stopping xterm")
    emss1.xterm_teardown()
